const messageRecipients = `-- name: MessageRecipients :many
WITH c AS (SELECT id, org_id, listing_id, seeker_id, prescreen_answers, blocked_by, blocked_at, last_message_at, created_at FROM conversations WHERE conversations.id = $1::uuid),
parties AS (
  SELECT c.seeker_id AS user_id FROM c
  UNION
  SELECT m.user_id FROM memberships m JOIN c ON m.org_id = c.org_id WHERE m.role IN ('owner', 'admin', 'agent')
)
SELECT u.id, u.email, u.locale, u.display_name,
  coalesce(r.last_read_at, 'epoch')::timestamptz AS last_read_at,
  coalesce(p.email_messages, 'instant')::text AS email_messages,
  coalesce(p.push_messages, true)::boolean AS push_messages
FROM parties
JOIN users u ON u.id = parties.user_id
LEFT JOIN conversation_reads r ON r.conversation_id = $1::uuid AND r.user_id = u.id
LEFT JOIN notification_preferences p ON p.user_id = u.id
WHERE u.id IS DISTINCT FROM $2::uuid AND u.pseudonymized_at IS NULL
`

