const systemPushDevices = `-- name: SystemPushDevices :many
SELECT id, user_id, platform, token, keys, label, created_at, last_seen_at FROM push_devices WHERE user_id = $1
`

func (q *Queries) SystemPushDevices(ctx context.Context, userID uuid.UUID) ([]PushDevice, error) {
	rows, err := q.db.Query(ctx, systemPushDevices, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PushDevice{}
	for rows.Next() {
		var i PushDevice
		if err := rows.Scan(
			&i.ID,
			&i.UserID,
			&i.Platform,
			&i.Token,
			&i.Keys,
			&i.Label,
			&i.CreatedAt,
			&i.LastSeenAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

